import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        HashSet<Long> positions = new HashSet<>(2 * n + 1);
        for (int i = 0; i < n; i++) positions.add(nextLong());
        for (int i = 0; i < m; i++) {
            long u = nextLong(), v = nextLong();
            positions.remove(u);
            positions.add(v);
        }
        long[] out = new long[positions.size()];
        int k = 0;
        for (long p : positions) out[k++] = p;
        Arrays.sort(out);
        StringBuilder sb = new StringBuilder();
        sb.append(out.length).append('\n');
        for (int i = 0; i < out.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(out[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	positions := make(map[int64]struct{}, n)
	for i := 0; i < n; i++ {
		positions[nextInt()] = struct{}{}
	}
	for i := 0; i < m; i++ {
		u, v := nextInt(), nextInt()
		delete(positions, u)
		positions[v] = struct{}{}
	}
	out := make([]int64, 0, len(positions))
	for p := range positions {
		out = append(out, p)
	}
	slices.Sort(out)
	buf := strconv.AppendInt(nil, int64(len(out)), 10)
	buf = append(buf, '\n')
	for i, p := range out {
		if i > 0 {
			buf = append(buf, ' ')
		}
		buf = strconv.AppendInt(buf, p, 10)
	}
	buf = append(buf, '\n')
	os.Stdout.Write(buf)
}
